-- SLA compliance by agent with sample size
-- Tables: tickets, sla_policies, agents
WITH e AS (SELECT t.*, p.target_resolution_minutes, CASE WHEN t.resolved_at IS NOT NULL THEN (julianday(t.resolved_at)-julianday(t.created_at))*1440 ELSE (julianday('now')-julianday(t.created_at))*1440 END AS elapsed FROM tickets t JOIN sla_policies p ON p.policy_id=t.policy_id) SELECT a.agent_name, COUNT(*) AS tickets, SUM(CASE WHEN e.resolved_at IS NOT NULL AND elapsed<=target_resolution_minutes THEN 1 ELSE 0 END) AS met, ROUND(100.0*SUM(CASE WHEN e.resolved_at IS NOT NULL AND elapsed<=target_resolution_minutes THEN 1 ELSE 0 END)/COUNT(*),2) AS sla_rate, ROUND(AVG(CASE WHEN e.resolved_at IS NOT NULL THEN elapsed END),1) AS avg_resolution_minutes FROM e JOIN agents a ON a.agent_id=e.agent_id GROUP BY a.agent_id HAVING COUNT(*)>=50 ORDER BY sla_rate;
